select case when a.balance >= 66000 then 'high' when a.balance >= 32000 then 'mid' else 'low' end as balance_bucket, avg(t.amount) as avg_amount from transactions t inner join accounts a on a.id = t.account_id where a.status <> 'OPEN' group by case when a.balance >= 66000 then 'high' when a.balance >= 32000 then 'mid' else 'low' end having avg(t.amount) >= 1400 order by balance_bucket desc limit 3;
